const envelopes=$input.all().map(i=>i.json);
const previous=new Set($('Ler historico').all().map(i=>i.json.content_key).filter(Boolean));
const all=[...new Map(envelopes.flatMap(e=>e.items||[]).map(i=>[i.content_key,i])).values()];
const unseen=all.filter(i=>!previous.has(i.content_key));
const now=new Date();
const sources=envelopes.map(e=>({id:e.source.id,name:e.source.name,kind:e.source.kind,feed_url:e.source.url,status:e.status,read_count:e.read_count,latest_at:e.latest_at,latest_age_days:e.latest_at?Math.floor((now-Date.parse(e.latest_at))/86400000):null,errors:e.errors||[]}));
const isEligible=i=>i.published_at&&Date.parse(i.published_at)<=now.getTime()+86400000&&i.age_days<=180&&i.excerpt.length>=20;
const isRelevant=i=>{
 const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const title=normalize(i.title);
 const t=normalize(i.title+' '+i.excerpt);
 if(i.kind==='dor_relatada')return (i.rating!==null&&i.rating<=3)||/dific|lento|erro|problema|demora|trava|nao consigo|perda|falha|atras|instabil/.test(t);
 if(/for hire|hiring|looking for work|weekly challenge|\[hire\]|\[job\]/.test(title))return false;
 if(/musicas para|principais sintomas|como tratar|como fazer.*anamnese/.test(title))return false;
 if(i.kind==='implementacao_comunidade')return /clinic|medic|patient|appointment|healthcare|booking|no.show|whatsapp|calendar|crm|lead|recepc|agend/.test(title);
 if(i.kind==='solucao_fornecedor')return /gestao|agend|marketing|divulg|fatur|fluxo|recep|automat|whatsapp|atend|prontuario|inteligencia|ia para|com ia|sistema/.test(title);
 if(/nvidia|dgx|gpu|roundup|funding/.test(title))return false;
 return /clinic|medic|patient|consult|gestao|agend|whatsapp|marketing|automat|workflow|agent| ai |intelig|crm|lead/.test(t);
};
const limits={iclinic_reviews:6,iclinic_blog:4,feegow_blog:4,n8n_blog:3,n8n_community:3};
const eligible=all.filter(isEligible).filter(isRelevant).sort((a,b)=>Date.parse(b.published_at)-Date.parse(a.published_at));
const selected=[];
for(const [source,limit] of Object.entries(limits))selected.push(...eligible.filter(i=>i.source_id===source&&!previous.has(i.content_key)).slice(0,limit));
const context=eligible.filter(i=>i.kind==='dor_relatada').slice(0,6).concat(eligible.filter(i=>i.kind==='solucao_fornecedor').slice(0,4));
const evidence=[...new Map(selected.concat(context).map(i=>[i.content_key,i])).values()].slice(0,30).map((i,n)=>({...i,evidence_id:'E'+String(n+1).padStart(2,'0'),is_new:!previous.has(i.content_key),freshness:i.age_days<=30?'ultimos_30_dias':'historico_31_a_180_dias',excerpt:i.excerpt.slice(0,2400)}));
const run_key=String($execution.id);
const generated_at=now.toISOString();
