const batch=$('Preparar lote').first().json;
const result=$input.first().json;
if(result.status&&result.status!=='completed')throw new Error('Resposta OpenAI incompleta: '+result.status);
const pieces=[];
for(const out of result.output||[]){for(const part of out.content||[]){if(part.type==='output_text'&&part.text)pieces.push(part.text);if(part.type==='refusal')throw new Error('OpenAI recusou a resposta.');}}
const raw=result.output_text||(pieces.length===1?pieces[0]:pieces.filter(p=>typeof p==='string').join('\n'))||(typeof result.text==='string'?result.text:null);
if(!raw)throw new Error('OpenAI nao retornou texto estruturado.');
const report=typeof raw==='object'?raw:JSON.parse(raw);
if(!report||typeof report.summary!=='string')throw new Error('Relatorio sem resumo valido.');
if(!Array.isArray(report.opportunities)||report.opportunities.length>3)throw new Error('Quantidade invalida de oportunidades.');
const index=new Map(batch.evidence.map(e=>[e.evidence_id,e]));
for(const op of report.opportunities){
 const pain=op.pain_source_ids||[];
 const solution=op.solution_source_ids||[];
 const ids=[...new Set(pain.concat(solution))];
 if(!ids.length||ids.some(id=>!index.has(id)))throw new Error('Citacao inexistente: '+op.title);
 if(!ids.some(id=>index.get(id).is_new))throw new Error('Pauta sem evidencia nova: '+op.title);
 if(op.evidence_level==='relato_individual'&&(!pain.length||pain.some(id=>index.get(id).kind!=='dor_relatada')))throw new Error('Relato de dor sem fonte de usuario.');
 if(op.evidence_level==='artigo_comercial'&&pain.some(id=>index.get(id).kind!=='solucao_fornecedor'))throw new Error('Motivacao comercial com fonte de dor incompativel.');
 if(solution.some(id=>index.get(id).kind==='dor_relatada'))throw new Error('Review nao valida solucao.');
 op.sources=ids.map(id=>{const e=index.get(id);return {evidence_id:id,title:e.title,url:e.url,published_at:e.published_at,source_name:e.source_name,kind:e.kind,freshness:e.freshness,is_new:e.is_new};});
 op.cta='Quer mapear um gargalo do seu consultório? Fale com a BPM.med por mensagem.';
 op.review_status='rascunho_revisao_humana';
}
const lines=['# Radar BPM.med',batch.generated_at,'',report.summary,'','Status: rascunhos para revisão humana.'];
if(batch.bootstrap)lines.push('Primeira carga: inclui histórico de até 180 dias; não representa tendências atuais.');
for(const [n,op] of report.opportunities.entries()){
 lines.push('','## '+(n+1)+'. '+op.title,'','Dor: '+op.pain_summary,'Evidência: '+op.evidence_level+' | Confiança: '+op.confidence,'','Ângulo: '+op.angle,'Formato: '+op.format,'Gancho: '+op.hook,'','Roteiro: '+op.script,'','CTA: '+op.cta,'Serviço possível: '+op.service_idea,'Verificar antes de publicar: '+op.verification_needed,'','Fontes:');
 for(const s of op.sources)lines.push('- ['+s.evidence_id+'] '+s.source_name+' — '+s.title+' ('+s.published_at.slice(0,10)+'; '+s.freshness+'): '+s.url);
}
lines.push('','## Coleta');
for(const s of batch.sources)lines.push('- '+s.name+': '+s.status+'; '+s.read_count+' itens; última publicação: '+(s.latest_at||'sem data'));
